setup:
$p: m.define-palette(m.$indigo-palette, 700, 200, 900, 300);
$a: m.define-palette(m.$pink-palette, A200, A100, A400);
$w: m.define-palette(m.$red-palette, 900);
$level: m.define-typography-level(19px, 27px, 600, 'Closeout Font', 0.03em);
$modern: m.define-typography-config($font-family: 'Custom Family', $body-1: $level, $button: $level);
$legacy: m.define-legacy-typography-config($font-family: 'Legacy Family', $body-1: $level, $button: $level);
$modern-light: m.define-light-theme((color: (primary: $p, accent: $a, warn: $w), typography: $modern, density: -2));
$modern-dark: m.define-dark-theme((color: (primary: $p, accent: $a, warn: $w), typography: $modern, density: -2));
$legacy-light: m.define-light-theme((color: (primary: $p, accent: $a, warn: $w), typography: $legacy, density: -2));
$legacy-dark: m.define-dark-theme((color: (primary: $p, accent: $a, warn: $w), typography: $legacy, density: -2));
